//! The error catalogue of spec/api/openapi.yaml (`x-mopm-errors`): each code's
//! HTTP status, message template and hint template. Generated by
//! tests/drivers/gen_errors.zig (//:gen_errors); do not edit by hand.
//! tests/contract/replay.py checks every error the fake sends against the
//! catalogue, and //:gen_errors_current checks that this file is what the
//! generator makes of the spec.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const Code = enum {
    invalid_request,
    invalid_name,
    invalid_version,
    upload_invalid,
    token_missing,
    token_unknown,
    token_expired,
    token_revoked,
    stale_session,
    oidc_token_invalid,
    scope_missing,
    not_owner,
    name_reserved,
    oidc_not_trusted,
    limit_exceeded,
    package_not_found,
    version_not_found,
    user_not_found,
    invitation_not_found,
    device_code_unknown,
    token_not_found,
    owner_not_found,
    publish_not_found,
    group_not_found,
    name_taken,
    name_too_similar,
    version_exists,
    already_owner,
    last_owner,
    upload_used,
    group_not_open,
    group_conflict,
    group_commit_refused,
    group_not_settled,
    invalid_transition,
    invitation_expired,
    payload_too_large,
    rate_limited,
    internal_error,
    read_only_mode,
    unavailable,
    route_not_found,
};

pub const Entry = struct { status: std.http.Status, message: []const u8, hint: []const u8 };

pub fn entry(code: Code) Entry {
    return switch (code) {
        .invalid_request => .{ .status = .bad_request, .message = "The request is not valid: {detail}.", .hint = "Check the request against the API documentation; update mopm if it is old." },
        .invalid_name => .{ .status = .bad_request, .message = "'{name}' is not a valid package name.", .hint = "Names are lowercase letters, digits and underscores, 2 to 64 characters, starting with a letter." },
        .invalid_version => .{ .status = .bad_request, .message = "'{version}' is not a valid version.", .hint = "A version is MAJOR.MINOR.PATCH: three numbers separated by dots, such as 1.2.3. Suffixes such as rc1 are not supported." },
        .upload_invalid => .{ .status = .bad_request, .message = "The upload does not match what was declared: {detail}.", .hint = "Begin a new upload with the real file name, sha256 and size." },
        .token_missing => .{ .status = .unauthorized, .message = "This request needs a token.", .hint = "Run 'mopm login' or pass a token." },
        .token_unknown => .{ .status = .unauthorized, .message = "The token is not recognised.", .hint = "Create a new token with 'mopm token create', or run 'mopm login'." },
        .token_expired => .{ .status = .unauthorized, .message = "The token expired at {expires_at}.", .hint = "Create a new token." },
        .token_revoked => .{ .status = .unauthorized, .message = "The token was revoked.", .hint = "Create a new token." },
        .stale_session => .{ .status = .unauthorized, .message = "This action needs a login from the last 15 minutes.", .hint = "Run 'mopm login' again." },
        .oidc_token_invalid => .{ .status = .unauthorized, .message = "The CI identity token was rejected: {detail}.", .hint = "Check the audience and that the job has permission to request an identity token." },
        .scope_missing => .{ .status = .forbidden, .message = "The token does not have the '{scope}' scope for '{name}'.", .hint = "Create a token with that scope and that package." },
        .not_owner => .{ .status = .forbidden, .message = "You are not an owner of '{name}'.", .hint = "Ask an owner to invite you." },
        .name_reserved => .{ .status = .forbidden, .message = "'{name}' is reserved.", .hint = "Choose another name." },
        .oidc_not_trusted => .{ .status = .forbidden, .message = "No trusted publisher of '{name}' matches this CI identity.", .hint = "Register the repository, workflow and environment as a trusted publisher of the package." },
        .limit_exceeded => .{ .status = .forbidden, .message = "Adding this file would put '{name}' over its storage limit of {limit} bytes; {remaining} bytes are left.", .hint = "Yanked versions still count toward the limit; only a takedown frees space. Reduce the package size." },
        .package_not_found => .{ .status = .not_found, .message = "There is no package '{name}'.", .hint = "Check the spelling, or claim the name." },
        .version_not_found => .{ .status = .not_found, .message = "'{name}' has no version '{version}'.", .hint = "List the versions with 'mopm info {name}'." },
        .user_not_found => .{ .status = .not_found, .message = "No GitHub account '{handle}'.", .hint = "Check the handle." },
        .invitation_not_found => .{ .status = .not_found, .message = "There is no such invitation for you.", .hint = "List yours with 'mopm invitations list'." },
        .device_code_unknown => .{ .status = .not_found, .message = "The device code is not recognised.", .hint = "Start the login again." },
        .token_not_found => .{ .status = .not_found, .message = "There is no such token.", .hint = "List yours with 'mopm token list'." },
        .owner_not_found => .{ .status = .not_found, .message = "That account is not an owner of '{name}'.", .hint = "List owners with 'mopm owners list'." },
        .publish_not_found => .{ .status = .not_found, .message = "There is no such publish.", .hint = "Publish ids are only valid for the caller who made them." },
        .group_not_found => .{ .status = .not_found, .message = "There is no such group.", .hint = "Group ids are only valid for the caller who made them, or for an owner of every package in the group." },
        .name_taken => .{ .status = .conflict, .message = "'{name}' is already taken.", .hint = "Choose another name." },
        .name_too_similar => .{ .status = .conflict, .message = "'{name}' is too similar to '{other}'.", .hint = "Choose another name, or claim again with confirm_similar if you are sure." },
        .version_exists => .{ .status = .conflict, .message = "'{name}' {version} already exists (sha256 {sha256}); versions are immutable.", .hint = "Publish a new version." },
        .already_owner => .{ .status = .conflict, .message = "'{handle}' already owns '{name}'.", .hint = "" },
        .last_owner => .{ .status = .conflict, .message = "'{handle}' is the last owner of '{name}'.", .hint = "Add another owner first." },
        .upload_used => .{ .status = .conflict, .message = "The upload '{upload_id}' was already used.", .hint = "Begin a new upload." },
        .group_not_open => .{ .status = .conflict, .message = "Group {group_id} is {status}; only an open group can be aborted.", .hint = "Create the group again with the same request to open it again." },
        .group_conflict => .{ .status = .conflict, .message = "The group cannot be created: {detail}.", .hint = "Abort or finish your other groups, or publish a new version." },
        .group_commit_refused => .{ .status = .conflict, .message = "The group cannot be committed: {detail}.", .hint = "Read the group with its status request; create it again with the same request to open it again." },
        .group_not_settled => .{ .status = .conflict, .message = "Group {group_id} cannot be yanked or unyanked now: {detail}.", .hint = "A group is yanked once it is visible, and not while another yank or unyank of it is running; read the group with its status request." },
        .invalid_transition => .{ .status = .conflict, .message = "Cannot {action} '{name}' {version}: it is {state}.", .hint = "Only a published version can be yanked, only a yanked version can be unyanked, and a tombstoned version never changes." },
        .invitation_expired => .{ .status = .gone, .message = "The invitation expired.", .hint = "Ask the owner to invite you again." },
        .payload_too_large => .{ .status = .payload_too_large, .message = "The file is larger than the limit of {limit} bytes.", .hint = "Reduce the package size." },
        .rate_limited => .{ .status = .too_many_requests, .message = "Too many requests.", .hint = "Wait {retry_after} seconds; the Retry-After header says how long." },
        .internal_error => .{ .status = .internal_server_error, .message = "Something went wrong on our side.", .hint = "Try again; report the request id if it persists." },
        .read_only_mode => .{ .status = .service_unavailable, .message = "The registry is read-only right now; new uploads are refused.", .hint = "Installs still work. Try again later." },
        .unavailable => .{ .status = .service_unavailable, .message = "The registry is temporarily unavailable.", .hint = "Try again shortly." },
        .route_not_found => .{ .status = .not_found, .message = "There is no such operation.", .hint = "Check the request against the API documentation; update mopm if it is old." },
    };
}

/// A template parameter: `{name}` in a message or hint.
pub const Param = struct { []const u8, []const u8 };

/// `template` with each `{key}` replaced by its value from `params`; a key
/// with no value is left as written.
pub fn fill(arena: Allocator, template: []const u8, params: []const Param) Allocator.Error![]const u8 {
    var out = std.ArrayList(u8).init(arena);
    var i: usize = 0;
    while (i < template.len) {
        if (template[i] == '{') {
            if (std.mem.indexOfScalarPos(u8, template, i, '}')) |end| {
                const key = template[i + 1 .. end];
                for (params) |p| {
                    if (std.mem.eql(u8, p[0], key)) {
                        try out.appendSlice(p[1]);
                        break;
                    }
                } else try out.appendSlice(template[i .. end + 1]);
                i = end + 1;
                continue;
            }
        }
        try out.append(template[i]);
        i += 1;
    }
    return try out.toOwnedSlice();
}

test "templates take their parameters" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    const e = entry(.version_not_found);
    try std.testing.expectEqual(std.http.Status.not_found, e.status);
    try std.testing.expectEqualStrings("'json' has no version '1.0'.", try fill(a, e.message, &.{ .{ "name", "json" }, .{ "version", "1.0" } }));
    try std.testing.expectEqualStrings("List the versions with 'mopm info {name}'.", try fill(a, e.hint, &.{}));
}
